"A Model Context Protocol server gives a coding agent extra tools: files, the web, a browser, GitHub and the like. This only reaches the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — an agent used only with an API key cannot use one here.": "Um servidor Model Context Protocol dá a um agente de programação ferramentas extras: arquivos, a web, um navegador, o GitHub e similares. Isto só alcança os agentes que fazem login pela própria ferramenta de linha de comando no Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — um agente usado apenas com uma chave de API não pode usar um aqui.",
