"Agent websites": "Sites dos agentes",
"Agent when the app opens": "Agente ao abrir o app",
"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "Os agentes agem por meio de quatro tipos de etapa: executar um comando, ler um arquivo, gravar um arquivo ou editar parte de um arquivo. Antes de um comando ser executado ou de um arquivo ser alterado, você vê exatamente o que será feito e escolhe Executar (ou Aplicar), Ignorar ou Sempre permitir pelo resto do chat. Ler arquivos na pasta atual não exige aprovação.",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "Os agentes podem errar. Leia o que eles querem executar, principalmente com o Modo de operação ou com Root, em que um comando pode remover apps ou alterar configurações.",
"Agents only see what you send and what their steps return; keys and tokens in output are hidden from them.": "Os agentes só veem o que você envia e o que as etapas deles retornam; chaves e tokens na saída ficam ocultos para eles.",
