"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "Escolha o método de login no painel de conexão do agente. Quando as ferramentas não têm versão para Android, elas são instaladas em um ambiente Debian dentro do Termux. Isso leva vários minutos e ocupa até cerca de 1 GB; os provedores não oferecem suporte oficial ao Android, então uma ferramenta pode não funcionar em todos os telefones.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "Escolha o que faz o botão extra de cada linha da lista de Apps. Ele é sempre um ícone, e os que mudam conforme o app (Ativar / Desativar, Instalar / Desinstalar, Cancelar suspensão / Suspender) trocam o ícone e a ação para corresponder ao estado atual do app.",
"Choosing files works in the app": "A escolha de arquivos funciona no app",
