"Edited": "Editadas",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "Editar um APK altera o conteúdo dele, e por isso a assinatura deixa de corresponder. O Android não o instalará até que seja assinado de novo: use Assinar (este app assina com uma chave própria).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "Editar um APK altera o conteúdo dele, e por isso a assinatura deixa de corresponder. O Android não o instalará até que seja assinado de novo; Assinar faz isso com uma chave deste app.",
"Effort": "Esforço",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "O esforço só muda algo para os agentes cuja própria API tem esse ajuste (Claude, ChatGPT, Gemini, Grok); para os demais ele é mantido, mas não tem efeito ao conversar por chave de API, e nenhum deles o repassa à própria ferramenta de login no Termux.",
