"Hands the queued files to Android's Bluetooth sharing, which asks which paired device gets them. Most watches, Wear OS included, cannot receive files this way: for a Wear OS watch use the Bluetooth link under Add device and send over ADB instead.": "Entrega os arquivos da fila ao compartilhamento por Bluetooth do Android, que pergunta qual dispositivo pareado deve recebê-los. A maioria dos relógios, inclusive os Wear OS, não consegue receber arquivos assim: para um relógio Wear OS, use a conexão Bluetooth em Adicionar dispositivo e envie por ADB.",
