"It could not be saved": "Não foi possível salvar",
"It did not finish": "Não foi concluído",
"It did not work": "Não funcionou",
"It finishes installing itself the first time it opens.": "Ele conclui a própria instalação na primeira vez que é aberto.",
"It goes back to the version that came with the phone. An older version often cannot use the data of a newer one, so it may lose its data.": "Ele volta à versão que veio com o telefone. Uma versão mais antiga muitas vezes não consegue usar os dados de uma mais nova, então ele pode perder os dados.",
"It has no Android build, so it goes into a Debian container inside Termux (several minutes, a few hundred MB). Already installed steps are skipped quickly.": "Não tem versão para Android, então vai para um contêiner Debian dentro do Termux (vários minutos, algumas centenas de MB). O que já estiver instalado é pulado rapidamente.",
"It is not set any more": "Não está mais definido",
"It is removed for the device's user. A system app can be put back with Reinstall.": "Ele é removido para o usuário do dispositivo. Um app do sistema pode ser restaurado com Reinstalar.",
"It is removed for you. A system app stays on the phone and can be brought back with Reinstall.": "Ele é removido para você. Um app do sistema permanece no telefone e pode ser restaurado com Reinstalar.",
"It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Primeiro ele é instalado como está; se o Android o recusar, é instalada uma cópia assinada com a chave deste app.",
"Its settings, accounts and files on the device are deleted.": "As configurações, contas e arquivos dele no dispositivo são excluídos.",
"Its settings, accounts, saved games and the files in its own storage are deleted. This cannot be undone.": "As configurações, contas, jogos salvos e os arquivos do armazenamento próprio dele são excluídos. Isso não pode ser desfeito.",
"IzzyOnDroid": "IzzyOnDroid",
"IzzyOnDroid page": "Página do IzzyOnDroid",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "O Jan roda modelos de IA no seu computador, de graça. No computador: Jan, Configurações, Local API Server: defina o host como 0.0.0.0 e inicie-o; depois, informe aqui o endereço do computador (como http://192.168.1.20:1337/v1). Não existe versão do Jan para Android.",
