"Keys are encrypted with a key that stays in the phone's secure hardware, and they are only ever sent to their own provider's address. The page never sees them again after you type them; only the last four characters are shown.": "As chaves são criptografadas com uma chave que fica no hardware seguro do telefone e só são enviadas ao endereço do próprio provedor. A página nunca mais as vê depois que você as digita; só os quatro últimos caracteres são mostrados.",
