"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "O Leon é um assistente pessoal de código aberto (habilidades, voz) que roda em um computador com Node.js e Python. Ele não tem versão para Android e não é um agente de código, por isso não conversa neste Terminal.",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "Deixar o Termux receber comandos de outros apps",
"Let them act without asking": "Deixar que ajam sem perguntar",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "Permite que o agente leia e grave arquivos na pasta indicada no fim do comando (altere /sdcard como preferir).",
