"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "Permite que este app instale os arquivos de pacote que você escolher, como arquivos APK, APKS e XAPK do seu armazenamento.",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "Permite que este app abra a tela de outro app em segundo plano, como um app que você acabou de instalar.",
