"The $ button switches to commands.": "O botão $ alterna para comandos.",
"The ADB key and the APK-signing key are created on this phone and never leave it.": "A chave ADB e a chave de assinatura de APK são criadas neste telefone e nunca saem dele.",
"The Action Button": "O botão de ação",
"The Bluetooth link could not be set up.": "Não foi possível configurar a conexão Bluetooth.",
"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "O botão MCP abre um painel para dar a um agente ferramentas extras (arquivos, a web, um navegador, o GitHub...) por meio do Model Context Protocol. Escolha uma predefinição ou escreva a sua: um nome, um comando local ou um endereço remoto, e qualquer chave ou cabeçalho necessário. Escolha a quais agentes adicioná-lo — o mesmo servidor pode ir para dois ou mais ao mesmo tempo, pois cada agente o guarda no próprio arquivo.",
"The PDF could not be shown.": "Não foi possível exibir o PDF.",
"The Rish shell ended. Tap Rish mode to open a new one.": "O shell Rish foi encerrado. Toque em Modo Rish para abrir um novo.",
"The Rish shell is no longer running.": "O shell Rish não está mais em execução.",
"The Terminal needs the app (it is not available in a plain browser)": "O Terminal precisa do app (não está disponível em um navegador comum)",
"The UAD-NG list has not been downloaded yet.": "A lista UAD-NG ainda não foi baixada.",
"The account has no credit left, or a spending limit was reached.": "A conta está sem crédito, ou um limite de gastos foi atingido.",
"The agent is still working: STOP it first": "O agente ainda está trabalhando: toque em STOP primeiro",
"The agent pauses after this many steps.": "O agente pausa depois desse número de etapas.",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "O app é gratuito e continuará assim. Se ele economizou seu tempo, um café me ajuda a continuar aprimorando-o. Totalmente opcional, e obrigado!",
