"The device's system, secure and global settings. A wrong value can make a device misbehave: change one at a time.": "As configurações System, Secure e Global do dispositivo. Um valor errado pode fazer um dispositivo se comportar mal: altere um de cada vez.",
"The edit could not start": "Não foi possível iniciar a edição",
"The extra keys work like Termux's: ESC clears the line, TAB completes a file name, CTRL-C stops what is running, the arrows go through earlier commands and move the cursor, HOME and END jump in the line, and | / - ~ are there because phone keyboards hide them.": "As teclas extras funcionam como as do Termux: ESC limpa a linha, TAB completa um nome de arquivo, CTRL-C interrompe o que está em execução, as setas percorrem os comandos anteriores e movem o cursor, HOME e END saltam dentro da linha, e | / - ~ estão aí porque os teclados de celular os escondem.",
"The extraction could not start": "Não foi possível iniciar a extração",
