"To browse files on this phone, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Para navegar pelos arquivos deste telefone, este app precisa do acesso a todos os arquivos (ou de um modo de operação: ADB, Shizuku ou Root).",
"To make this the default installer, open any APK, choose this app, and tap \"Always\".": "Para tornar este o instalador padrão, abra qualquer APK, escolha este app e toque em “Sempre”.",
"To search storage for APK, APKS, APKM and XAPK files, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Para pesquisar arquivos APK, APKS, APKM e XAPK no armazenamento, este app precisa do acesso a todos os arquivos (ou de um modo de operação: ADB, Shizuku ou Root).",
"To search storage for fonts, this app needs All-files access. You can also choose a font file by hand, which needs no access.": "Para procurar fontes no armazenamento, este app precisa do acesso a todos os arquivos. Você também pode escolher um arquivo de fonte manualmente, o que não exige acesso.",
