"To use DroidMind with an agent that speaks MCP (such as Claude Code or OpenCode), install it into the Debian container in Termux. Then start it with droidmind --transport sse and add it to that agent as an MCP server.": "Para usar o DroidMind com um agente compatível com MCP (como o Claude Code ou o OpenCode), instale-o no contêiner Debian do Termux. Depois, inicie-o com droidmind --transport sse e adicione-o a esse agente como servidor MCP.",
